(2318482, 321876, 22856, '<td valign="top">To much air above her head.</td>', 'To much air above her head.', '2006-04-17 10:12:31.000000', NULL, 1),
(2318490, 320587, 32254, '<td valign="top">Nice.. has a Kevyn Major Howard feel to it.</td>', 'Nice.. has a Kevyn Major Howard feel to it.', '2006-04-17 10:15:11.000000', NULL, 1),
(2318491, 320063, 32254, '<td valign="top">I like, very emotional, I dig the background too.</td>', 'I like, very emotional, I dig the background too.', '2006-04-17 10:15:37.000000', NULL, 1),
(2318492, 321898, 32254, '<td valign="top">Dr Phil?! Cool shot, I like the shadows.</td>', 'Dr Phil?! Cool shot, I like the shadows.', '2006-04-17 10:16:11.000000', NULL, 1),
(2318493, 321027, 38592, '<td valign="top">White balance seems a bit to the yellow side and the painting in the background is crooked.  A little bit of mood lighting rather than just full on, would have made this picture pop a bit more.</td>', 'White balance seems a bit to the yellow side and the painting in the background is crooked.  A little bit of mood lighting rather than just full on, would have made this picture pop a bit more.', '2006-04-17 10:16:23.000000', NULL, 1),
(2318494, 321827, 22856, '<td valign="top">Abit too dark.</td>', 'Abit too dark.', '2006-04-17 10:16:46.000000', NULL, 1),
(2318495, 322008, 32254, '<td valign="top">You''ll probably get some complaints about the space on the right, but I like the composition.</td>', 'You''ll probably get some complaints about the space on the right, but I like the composition.', '2006-04-17 10:16:54.000000', NULL, 1),
(2318496, 321967, 32254, '<td valign="top">Usually not big on the kid shots, but this outstanding.</td>', 'Usually not big on the kid shots, but this outstanding.', '2006-04-17 10:17:26.000000', NULL, 1),
(2318497, 321901, 38592, '<td valign="top">Looks a bit under exposed.</td>', 'Looks a bit under exposed.', '2006-04-17 10:17:37.000000', NULL, 1),
