(2321031, 321963, 43156, '<td valign="top">Very funny and very well executed.</td>', 'Very funny and very well executed.', '2006-04-18 02:17:28.000000', NULL, 1),
(2321034, 320965, 55642, '<td valign="top">My suggestion here is merely to crop the distracting blur out from the lower right corner. Otherwise, this is beautiful. :-)</td>', 'My suggestion here is merely to crop the distracting blur out from the lower right corner. Otherwise, this is beautiful. :-)', '2006-04-18 02:22:08.000000', NULL, 1),
