INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2332177, 322008, 54731, '<td valign="top">Good use of light, don''t like her expression that much... 7</td>', 'Good use of light, don''t like her expression that much... 7', '2006-04-21 09:15:39.000000', NULL, 1),
(2332201, 321201, 54731, '<td valign="top">Good use of light here.</td>', 'Good use of light here.', '2006-04-21 09:28:01.000000', NULL, 1),
(2332207, 321315, 54731, '<td valign="top">Great idea!</td>', 'Great idea!', '2006-04-21 09:32:35.000000', NULL, 1),
(2332209, 320504, 54731, '<td valign="top">Great effect!</td>', 'Great effect!', '2006-04-21 09:33:46.000000', NULL, 1),
(2332211, 321858, 47852, '<td valign="top">Adorable shot!  Nice to see a portrait that tells the viewer something about the person.  Well done and one of my favorites from the challenge!</td>', 'Adorable shot!  Nice to see a portrait that tells the viewer something about the person.  Well done and one of my favorites from the challenge!', '2006-04-21 09:36:47.000000', NULL, 1),
(2332213, 321639, 54731, '<td valign="top">Too much skin softening here...</td>', 'Too much skin softening here...', '2006-04-21 09:38:09.000000', NULL, 1),
(2332215, 321878, 47852, '<td valign="top">Love the background, the consistency of color and the expression.  They all work well together to portray an emotion and not just another boring portrait of a person.  Very well done! :)</td>', 'Love the background, the consistency of color and the expression.  They all work well together to portray an emotion and not just another boring portrait of a person.  Very well done! :)', '2006-04-21 09:38:44.000000', NULL, 1),
(2332218, 321864, 47852, '<td valign="top">A fun and unique idea for a portrait.  It tells something about you and your hobbies and is well composed.  Nice job!</td>', 'A fun and unique idea for a portrait.  It tells something about you and your hobbies and is well composed.  Nice job!', '2006-04-21 09:40:00.000000', NULL, 1),
(2332220, 321506, 47852, '<td valign="top">Very intense portrait.  There are other shots where the subject is looking at the camera, but this one really just draws you in.</td>', 'Very intense portrait.  There are other shots where the subject is looking at the camera, but this one really just draws you in.', '2006-04-21 09:41:09.000000', NULL, 1),
(2332226, 320967, 47852, '<td valign="top">Love the idea of having the 2 girls in the background... really gives a sense of who this person is.  Technically well done, interesting composition and unique idea.  Fantastic job!</td>', 'Love the idea of having the 2 girls in the background... really gives a sense of who this person is.  Technically well done, interesting composition and unique idea.  Fantastic job!', '2006-04-21 09:42:32.000000', NULL, 1),
(2332234, 321839, 47852, '<td valign="top">There are lots of simple portraits in the challenge, but this one seems very real and casual.  The clothing looks like everyday, casual wear, and the smile seems more genuine than some of the others.  Overall a well captured shot!</td>', 'There are lots of simple portraits in the challenge, but this one seems very real and casual.  The clothing looks like everyday, casual wear, and the smile seems more genuine than some of the others.  Overall a well captured shot!', '2006-04-21 09:44:08.000000', NULL, 1),
