(2334949, 321408, 49315, '<td valign="top">Definately a fave</td>', 'Definately a fave', '2006-04-22 13:42:34.000000', NULL, 1),
(2334971, 320965, 56999, '<td valign="top">Beautiful picture telling a wonderful story.</td>', 'Beautiful picture telling a wonderful story.', '2006-04-22 14:14:01.000000', NULL, 1),
(2334973, 321858, 56999, '<td valign="top">Wonderful image.</td>', 'Wonderful image.', '2006-04-22 14:16:58.000000', NULL, 1),
