(2336282, 321328, 48954, '<td valign="top">wow. hot stuff</td>', 'wow. hot stuff', '2006-04-23 11:00:42.000000', NULL, 1),
(2336283, 321939, 48954, '<td valign="top">hm, could be sharper.</td>', 'hm, could be sharper.', '2006-04-23 11:01:28.000000', NULL, 1),
