INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2337488, 321848, 39057, '<td valign="top">I tell ya what...you''re not worried about lowering your "average" score. You seem to enter really good shots or really fun shots. It shows that you have fun with the cam and you are not worried too much about what other''s think...<br/> <br/>6</td>', 'I tell ya what...you''re not worried about lowering your "average" score. You seem to enter really good shots or really fun shots. It shows that you have fun with the cam and you are not worried too much about what other''s think... 6', '2006-04-23 23:11:14.000000', NULL, 1),
